package com.andye.warmod.radar.client.gui;
import com.andye.warmod.radar.RadarTerrainTile;import com.andye.warmod.radar.client.*;import net.minecraft.client.gui.GuiGraphicsExtractor;
public final class RadarMapRenderer{private RadarMapRenderer(){}public static void render(GuiGraphicsExtractor g,ClientRadarState state,RadarMapTransform t,double now,int l,int top,int w,int h){g.fill(l,top,l+w,top+h,0xff05090b);g.enableScissor(l,top,l+w,top+h);if(t.blocksPerPixel()<=8)terrain(g,state,t,l,top,w,h);else grid(g,t,l,top,w,h);for(ClientRadarImpact i:state.impacts())RadarImpactRenderer.render(g,i,t,now,l,top,w,h);for(ClientRadarTrack track:state.tracks())RadarTrackRenderer.render(g,track,t,now,l,top,w,h,track.id().equals(state.selectedTrackId()));g.disableScissor();}private static void terrain(GuiGraphicsExtractor g,ClientRadarState state,RadarMapTransform t,int l,int top,int w,int h){for(RadarTerrainTile tile:state.terrainCache().values()){int[] colors=tile.colours();for(int z=0;z<8;z++)for(int x=0;x<8;x++){double wx=(tile.chunkX()<<4)+x*2,wz=(tile.chunkZ()<<4)+z*2;int x0=(int)t.screenX(wx,l,w),y0=(int)t.screenY(wz,top,h),x1=(int)Math.ceil(t.screenX(wx+2,l,w)),y1=(int)Math.ceil(t.screenY(wz+2,top,h));if(x1>=l&&x0<l+w&&y1>=top&&y0<top+h)g.fill(x0,y0,Math.max(x0+1,x1),Math.max(y0+1,y1),colors[z*8+x]);}}}private static void grid(GuiGraphicsExtractor g,RadarMapTransform t,int l,int top,int w,int h){double spacing=Math.pow(2,Math.ceil(Math.log(t.blocksPerPixel()*80)/Math.log(2)));double minX=t.worldX(l,l,w),maxX=t.worldX(l+w,l,w),minZ=t.worldZ(top,top,h),maxZ=t.worldZ(top+h,top,h);for(double x=Math.ceil(minX/spacing)*spacing;x<=maxX;x+=spacing){int sx=(int)t.screenX(x,l,w);g.fill(sx,top,sx+1,top+h,0xff162126);}for(double z=Math.ceil(minZ/spacing)*spacing;z<=maxZ;z+=spacing){int sy=(int)t.screenY(z,top,h);g.fill(l,sy,l+w,sy+1,0xff162126);}}}
